param([string]$SearchBase)
Get-ADComputer -SearchBase $SearchBase -Filter {Enabled -eq $true} | ForEach-Object {
  $h = $_.DNSHostName
  try { Invoke-Command -ComputerName $h -ScriptBlock { Get-LocalGroupMember -Group Administrators } -ErrorAction Stop |
    Select-Object @{n='Host';e={$h}}, Name, PrincipalSource } catch { [pscustomobject]@{Host=$h;Name='<unreachable>';PrincipalSource=''} }
}
